args.command:
node --input-type=module - <<'EOF'
import { permit } from './limit.mjs';
const cases = [[-1,false],[0,true],[3,true],[4,false],['1',false],[null,false],[NaN,false],[1.5,false]];
for (const [input, expected] of cases) {
  const actual = permit(input);
  console.log(`${String(input)} -> ${actual} (expected ${expected})`);
  if (actual !== expected) process.exitCode = 1;
}
EOF
